def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = next(v for v in counts if v != background)
    out = [row[:] for row in grid]

    # Join successive marks horizontally.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == foreground]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Join vertical marks except when there are exactly two and both are
    # already part of horizontal strokes (these are horizontal bars, not a
    # separate vertical stroke).
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == foreground]
        if len(rows) == 2:
            def horizontal(r):
                return ((c > 0 and grid[r][c - 1] == foreground) or
                        (c + 1 < w and grid[r][c + 1] == foreground))
            if horizontal(rows[0]) and horizontal(rows[1]):
                continue
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
